3. Iterate through each entry to verify 'Country' is a string and 'Population' is a non-negative number.
4. Apply floor rounding to population values to ensure they are integers.
5. Construct a pandas DataFrame with the validated data.
6. Ensure the output directory exists and write the DataFrame to a CSV file without the index.
7. Return the absolute file path and the DataFrame.
8. Raise ValueError for data validation issues and IOError for file writing failures.

### code
```python
import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        if isinstance(json_data, str):
            data = json.loads(json_data)
        else:
            data = json_data

        if not data:
            raise ValueError("Data is empty")

        if not isinstance(data, list):
            raise ValueError("Data must be a list")

        processed_rows = []
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Item must be a dictionary")
            if 'Country' not in item or 'Population' not in item:
                raise ValueError("Missing Country or Population key")

            country = item['Country']
            population = item['Population']

            if not isinstance(country, str):
                raise ValueError("Country name must be a string")

            if not isinstance(population, (int, float)) or population < 0:
                raise ValueError("Population must be numeric and non-negative")

            processed_rows.append({
                'Country': country,
                'Population': math.floor(population)
            })

        df = pd.DataFrame(processed_rows)

        if not os.path.exists(output_dir):
            os.makedirs(output_dir, exist_ok=True)

        file_path = os.path.join(output_dir, file_name)
        abs_path = os.path.abspath(file_path)

        try:
            df.to_csv(file_path, index=False)
        except Exception as e:
            raise IOError(f"Failed to write file: {e}")

        return abs_path, df

    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    except (ValueError, IOError):
        raise
    except Exception as e:
        raise ValueError(str(e))
